-- Synthetic schema derived from user-supplied metadata. NO production records.
CREATE ROLE anon NOLOGIN;
CREATE ROLE authenticated NOLOGIN;
CREATE SCHEMA auth;
CREATE SCHEMA storage;
CREATE TABLE auth.users(id uuid PRIMARY KEY,email text,email_confirmed_at timestamptz);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $$;
GRANT USAGE ON SCHEMA auth,public,storage TO anon,authenticated;
GRANT EXECUTE ON FUNCTION auth.uid() TO anon,authenticated;
CREATE TABLE public.groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,owner_user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,is_personal boolean NOT NULL DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE public.group_members(group_id uuid REFERENCES public.groups ON DELETE CASCADE,user_id uuid REFERENCES auth.users ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('owner','member')),created_at timestamptz DEFAULT now(),PRIMARY KEY(group_id,user_id));
CREATE TABLE public.profiles(user_id uuid PRIMARY KEY REFERENCES auth.users ON DELETE CASCADE,display_name text,email text,role text DEFAULT 'user',plan text DEFAULT 'free',created_at timestamptz DEFAULT now());
CREATE TABLE public.invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text NOT NULL,group_id uuid NOT NULL,invited_by uuid,status text DEFAULT 'pending',created_at timestamp DEFAULT now());
CREATE TABLE public.item_master(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name text NOT NULL,yomi text DEFAULT '',category text DEFAULT 'その他',note text DEFAULT '',image_url text);
CREATE TABLE public.user_item_master(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,name text NOT NULL,category text,yomi text,image_url text,created_at timestamptz DEFAULT now());
CREATE TABLE public.shopping_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,name text NOT NULL,category text NOT NULL DEFAULT 'その他',note text,checked boolean DEFAULT false,created_at timestamptz DEFAULT now(),image_url text,group_id uuid REFERENCES public.groups ON DELETE SET NULL);
CREATE TABLE public.deleted_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id uuid NOT NULL,name text NOT NULL,category text,note text,checked boolean,deleted_at timestamptz DEFAULT now(),group_id uuid,purchased_by_name text);
CREATE TABLE public.recipes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,name text NOT NULL,image_url text,image_path text,source_url text,instructions text,memo text,is_favorite boolean DEFAULT false,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),category text,servings integer);
CREATE TABLE public.recipe_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipe_id uuid NOT NULL REFERENCES public.recipes ON DELETE CASCADE,item_master_id bigint REFERENCES public.item_master,user_item_master_id bigint REFERENCES public.user_item_master,item_type text DEFAULT 'ingredient',amount_text text DEFAULT '',sort_order integer DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),CHECK(((item_master_id IS NOT NULL)::int+(user_item_master_id IS NOT NULL)::int)=1));
CREATE TABLE public.meal_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users ON DELETE CASCADE,group_id uuid REFERENCES public.groups ON DELETE CASCADE,name text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,servings integer,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now(),CHECK(end_date=start_date+6));
CREATE TABLE public.meal_plan_entries(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,meal_plan_id uuid REFERENCES public.meal_plans ON DELETE CASCADE,meal_date date NOT NULL,meal_type text DEFAULT 'dinner',recipe_id uuid REFERENCES public.recipes ON DELETE SET NULL,title text NOT NULL,sort_order integer DEFAULT 0,created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text,owner uuid,owner_id text,metadata jsonb);
-- Reproduce the most dangerous legacy policy: migration must remove it.
ALTER TABLE public.shopping_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "allow all for everyone" ON public.shopping_items TO PUBLIC USING(true) WITH CHECK(true);
GRANT ALL ON ALL TABLES IN SCHEMA public,storage TO anon,authenticated;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon,authenticated;
